/// <summary>
///
/// </summary>
void setColumns2Display(NDXMEDataFromExcelTable _dataFromExcelTable)
{
    #define.fg_Sonstiges("Sonstiges")


    NDXExcelLineDict   lNDX_ExcelLineDict;
    boolean             lColumnExists;
    FormDataObject      formDataObject;

    int                 i;
    container           conFieldId;

    FormDataSource      fds;

    ;
    // alle Felder der Tabelle durchlaufen
    while select lNDX_ExcelLineDict where lNDX_ExcelLineDict.TableId1 == tablenum(NDXMEDataFromExcelLine)
    {
        // Wurde dieses Feld importiert?
        lColumnExists = NDXExcelLine::existsExcelFieldId2(_dataFromExcelTable.XLSFileId, lNDX_ExcelLineDict.ExcelColumnName);

        for (i=1; i<=2; i++)
        {
            switch (i)
            {
                case 1: 
                    {
                        fds = NDXMEDataFromExcelLine_DS;                            
                        break;
                    }
                case 2: 
                    {
                        fds = NDXMEDataFromExcelLine_1_DS;
                        break;
                    }
            }

            formDataObject = fds.object(lNDX_ExcelLineDict.FieldId1);
            if (formDataObject)
            {
                if (lColumnExists)
                {
                    if (i == 1)
                    {
                        conFieldId += lNDX_ExcelLineDict.FieldId1;
                    }
                    if (!formDataObject.visible())
                    {
                        formDataObject.visible(lColumnExists);
                    }
                }
                else
                {
                    if (formDataObject.visible())
                    {
                        formDataObject.visible(lColumnExists);
                    }
                }
            }
        }
    }
}

/// <summary>
/// DebuC 06.02.25
/// </summary>
/// <param name = "setFilter">boolean</param>
/// <param name = "errorFilter">NDXErrorFilter</param>
void setFilterItemSum(boolean setFilter, NDXErrorFilter errorFilter)
{
    QueryBuildRange         qbr;
    QueryBuildDataSource    qbds;
    Query                   q;
    ;
    q = NDXMEDataFromExcelLine_2_ds.queryRun().query();
    qbds = q.dataSourceTable(tablenum(NDXMEDataFromExcelLine));
    qbr = SysQuery::findOrCreateRange(qbds, fieldnum(NDXMEDataFromExcelLine, ErrorInLine));
    qbr.value(setFilter ? QueryValue(errorFilter == NDXErrorFilter::exclusive ? NoYes::Yes : NoYes::No) :  SysQuery::valueUnlimited());
    NDXMEDataFromExcelLine_2_ds.query(q);
    NDXMEDataFromExcelLine_2_ds.executeQuery();
}

