/// <summary>
/// DebuC 14.05.25
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource        qbdsPos, qbdsSum;
    QueryBuildRange             qbr;
    int                         i;
    ;
    super();
    qbdsPos = NDXMEDataFromExcelLine_2_ds.queryRun().query().dataSourceTable(tablenum(NDXMEDataFromExcelLine));

    qbdsSum = NDXMEDataFromExcelLine_Sum_5_ds.query().dataSourceTable(tablenum(NDXMEDataFromExcelLine));
    qbdsSum.clearRanges();

    for (i=1; i <= qbdsPos.rangeCount(); i++)
    {
        qbr = qbdsPos.range(i);
        qbdsSum.addRange(qbr.field()).value(qbr.value());
    }
    NDXMEDataFromExcelLine_Sum_5_ds.executeQuery();
}

