/// <summary>
/// DebuC 14.05.25
/// </summary>
public void executeQuery()
{
    NDXVerband      nDX_Verband;
    CustAccount     masterAlliance;
    container       conMasterAlliance;
    ;

    if (!NDXMEDataFromExcelTable.CustAccount)
    {                
        return;
    }

    if (itemIdForFilter)
    {
        // höchste Ebene des Verbandes ermitteln
        nDX_Verband = NDXVerband::constructor(); 
        [masterAlliance, conMasterAlliance] = nDX_Verband.getMaster(NDXMEDataFromExcelTable.CustAccount);

        qbrCustomerAllianceAlliance.value(masterAlliance);
        qbrCustInvoiceJourItemId.value(itemIdForFilter);

        super();
    }
}

