/// <summary>
/// DebuC 13.05.25
/// </summary>
public void clicked()
{
    Dialog                      dialog = new Dialog(strfmt("@NXD9551 - Dateikennung: %1", NDXMEDataFromExcelTable.XLSFileNotice));
    DialogField                 dialogField;
    NDXExcelTable              lNDX_ExcelTable;

    ;

    super();
    dialogField = dialog.addField(identifierStr(NDXCount), "Anzahl Zeilen");
    if(dialog.run())
    {
        lNDX_ExcelTable = NDXExcelTable::find(NDXMEDataFromExcelTable.XLSFileId);

        lNDX_ExcelTable.FromRow         = NDXMEDataFromExcelTable.vonZeile;
        lNDX_ExcelTable.ToRow           = NDXMEDataFromExcelTable.vonZeile + dialogField.value() - 1;
        lNDX_ExcelTable.ExcelWorksheet   = NDXMEDataFromExcelTable.ExcelWorksheet;
        lNDX_ExcelTable.FileName         = NDXMEDataFromExcelTable.FileNameWithoutExtension;
        lNDX_ExcelTable.FilePath        = NDXMEDataFromExcelTable.FileName;

        NDXMarginEqualizing::getXlsData(lNDX_ExcelTable, NDXMEDataFromExcelTable, true);

        NDXMEDataFromExcelLine_DS.executeQuery();
        NDXMEDataFromExcelLine_1_DS.executeQuery();
        NDXMEDataFromExcelTable_DS.reread();
        NDXMEDataFromExcelTable_DS.refresh();
        NDXMEDataFromExcelLine_4_DS.executeQuery();
    }
}

